# Let me try to find GDP data by searching for specific quarter/year combinations
# in the format where the data may be embedded in tables or narrative

import re
import json

# First check in the 2016 bulletin JSON for all possible GDP data years
with open('/app/resources/treasury_bulletin_2016_03.json') as f:
    data2016 = json.load(f)

elements16 = data2016['document']['elements']

# Get all text elements
all_text = ""
for el in elements16:
    if el.get('type') == 'text':
        all_text += el.get('content', '') + " "

# Now find all quarter references
quarters_found = {}
for year in range(2010, 2017):
    for q in range(1, 5):
        quarter_pattern = rf'Q{q}\s+{year}'
        matches = re.findall(quarter_pattern, all_text)
        if matches:
            quarters_found[f"Q{q} {year}"] = len(matches)

print("Quarters found in 2016 bulletin:")
for k, v in sorted(quarters_found.items()):
    print(f"  {k}: {v}")

# Check 2020 bulletin
with open('/app/resources/treasury_bulletin_2020_03.json') as f:
    data2020 = json.load(f)

elements20 = data2020['document']['elements']

all_text = ""
for el in elements20:
    if el.get('type') == 'text':
        all_text += el.get('content', '') + " "

quarters_found = {}
for year in range(2013, 2021):
    for q in range(1, 5):
        quarter_pattern = rf'Q{q}\s+{year}'
        matches = re.findall(quarter_pattern, all_text)
        if matches:
            quarters_found[f"Q{q} {year}"] = len(matches)

print("\nQuarters found in 2020 bulletin:")
for k, v in sorted(quarters_found.items()):
    print(f"  {k}: {v}")
