# Let me try exhaustive search for any table element that may contain GDP rows
import json
import re

# Search both bulletins for any page elements with quarterly tables
# Table might have rows like "<tr><td>2013 Q1</td><td>...</td></tr>"

files = [
    '/app/resources/treasury_bulletin_2020_03.json',
    '/app/resources/treasury_bulletin_2016_03.json'
]

for fnam in files:
    print(f"\n=== Searching {fnam} ===")
    with open(fnam) as f:
        data = json.load(f)

    for el in data['document']['elements']:
        if el.get('type') == 'table':
            content = el.get('content', '')
            # Look for "Q1" pattern combined with numbers or year pattern
            if 'Q1' in content or 'Q2' in content or 'Q3' in content or 'Q4' in content:
                if 'percent' in content.lower() or 'rate' in content.lower():
                    print("Possible table:")
                    print(content[:400])

# Also look for pattern: year Q# or quarter year in data
# Search for year and quarter pattern in table rows
for fnam in files:
    with open(fnam) as f:
        data = json.load(f)
    for el in data['document']['elements']:
        if el.get('type') == 'table':
            content = str(el.get('content', ''))
            # Check for year quarter pattern like "2013" and "<td"
            if re.search(r'<td>\s*201[3-9]', content):
                if 'percent' in content.lower():
                    print(f"\nFound year rows in table {el.get('id')}:")
                    # Show rows
                    rows = re.findall(r'<tr>.*?</tr>', content, re.DOTALL)
                    for i,row in enumerate(rows[:10]):
                        if any(str(y) in row for y in range(2013, 2020)):
                            print(f"Row: {row[:200]}")
EOF
